use std::collections::{BTreeSet, HashMap, HashSet};

use super::geometry::{Path64, Paths64, Rect64};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FillRule {
    EvenOdd,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Operation {
    Intersection,
    Union,
    Difference,
    Xor,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct Run {
    left: i64,
    right: i64,
}

#[allow(non_snake_case)]
pub fn Intersect(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    boolean_paths(subjects, clips, Operation::Intersection)
}

#[allow(non_snake_case)]
pub fn Union(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    boolean_paths(subjects, clips, Operation::Union)
}

#[allow(non_snake_case)]
pub fn Difference(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    boolean_paths(subjects, clips, Operation::Difference)
}

#[allow(non_snake_case)]
pub fn Xor(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    boolean_paths(subjects, clips, Operation::Xor)
}

fn boolean_paths(subjects: &Paths64, clips: &Paths64, operation: Operation) -> Paths64 {
    match (collect_rects(subjects), collect_rects(clips)) {
        (Some(subject_rects), Some(clip_rects)) => {
            boolean_rects(&subject_rects, &clip_rects, operation)
        }
        _ => fallback(subjects, clips, operation),
    }
}

fn collect_rects(paths: &Paths64) -> Option<Vec<Rect64>> {
    paths.iter().map(Rect64::from_path).collect::<Option<Vec<_>>>()
}

fn boolean_rects(subjects: &[Rect64], clips: &[Rect64], operation: Operation) -> Paths64 {
    let mut x_coords = BTreeSet::new();
    let mut y_coords = BTreeSet::new();

    for rect in subjects.iter().chain(clips.iter()) {
        x_coords.insert(rect.left);
        x_coords.insert(rect.right);
        y_coords.insert(rect.top);
        y_coords.insert(rect.bottom);
    }

    let xs: Vec<i64> = x_coords.into_iter().collect();
    let ys: Vec<i64> = y_coords.into_iter().collect();

    if xs.len() < 2 || ys.len() < 2 {
        return Vec::new();
    }

    let mut filled = vec![vec![false; xs.len() - 1]; ys.len() - 1];

    for row in 0..(ys.len() - 1) {
        for col in 0..(xs.len() - 1) {
            let left = xs[col];
            let right = xs[col + 1];
            let top = ys[row];
            let bottom = ys[row + 1];

            let in_subject = subjects
                .iter()
                .any(|rect| rect.covers_cell(left, right, top, bottom));
            let in_clip = clips
                .iter()
                .any(|rect| rect.covers_cell(left, right, top, bottom));

            filled[row][col] = match operation {
                Operation::Intersection => in_subject && in_clip,
                Operation::Union => in_subject || in_clip,
                Operation::Difference => in_subject && !in_clip,
                Operation::Xor => in_subject ^ in_clip,
            };
        }
    }

    decompose_grid(&xs, &ys, &filled)
        .into_iter()
        .map(Rect64::to_path)
        .collect()
}

// Convert occupied grid cells into deterministic, non-overlapping rectangles.
fn decompose_grid(xs: &[i64], ys: &[i64], filled: &[Vec<bool>]) -> Vec<Rect64> {
    let mut rects = Vec::new();
    let mut active: HashMap<Run, i64> = HashMap::new();

    for row_index in 0..filled.len() {
        let runs = build_row_runs(xs, &filled[row_index]);
        let run_set: HashSet<Run> = runs.iter().copied().collect();

        let stale_runs: Vec<Run> = active
            .keys()
            .copied()
            .filter(|run| !run_set.contains(run))
            .collect();

        for run in stale_runs {
            if let Some(top) = active.remove(&run) {
                rects.push(Rect64 {
                    left: run.left,
                    top,
                    right: run.right,
                    bottom: ys[row_index],
                });
            }
        }

        for run in runs {
            active.entry(run).or_insert(ys[row_index]);
        }
    }

    let final_bottom = ys.last().copied().unwrap_or_default();
    for (run, top) in active {
        rects.push(Rect64 {
            left: run.left,
            top,
            right: run.right,
            bottom: final_bottom,
        });
    }

    rects.sort_by_key(|rect| (rect.top, rect.left, rect.bottom, rect.right));
    rects
}

fn build_row_runs(xs: &[i64], row: &[bool]) -> Vec<Run> {
    let mut runs = Vec::new();
    let mut start = None;

    for index in 0..row.len() {
        match (start, row[index]) {
            (None, true) => start = Some(index),
            (Some(run_start), false) => {
                runs.push(Run {
                    left: xs[run_start],
                    right: xs[index],
                });
                start = None;
            }
            _ => {}
        }
    }

    if let Some(run_start) = start {
        runs.push(Run {
            left: xs[run_start],
            right: xs[row.len()],
        });
    }

    runs
}

fn fallback(subjects: &Paths64, clips: &Paths64, operation: Operation) -> Paths64 {
    match operation {
        Operation::Intersection => Vec::<Path64>::new(),
        Operation::Union | Operation::Xor => {
            let mut combined = subjects.clone();
            combined.extend(clips.iter().cloned());
            combined
        }
        Operation::Difference => subjects.clone(),
    }
}

