#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub const fn new(x: i64, y: i64) -> Self {
        Self { x, y }
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub fn from_path(path: &Path64) -> Option<Self> {
        if path.len() < 4 {
            return None;
        }

        let mut xs: Vec<i64> = path.iter().map(|point| point.x).collect();
        let mut ys: Vec<i64> = path.iter().map(|point| point.y).collect();
        xs.sort_unstable();
        ys.sort_unstable();
        xs.dedup();
        ys.dedup();

        if xs.len() != 2 || ys.len() != 2 {
            return None;
        }

        let corners = [
            Point64::new(xs[0], ys[0]),
            Point64::new(xs[1], ys[0]),
            Point64::new(xs[1], ys[1]),
            Point64::new(xs[0], ys[1]),
        ];

        if !corners.iter().all(|corner| path.contains(corner)) {
            return None;
        }

        Some(Self {
            left: xs[0],
            top: ys[0],
            right: xs[1],
            bottom: ys[1],
        })
